    alias: {
      "@": path.resolve(__dirname, "./src"),
    },
  },
})

import axios from 'axios';

// When served by FastAPI, the base URL should be relative to the current origin.
// This ensures connectivity regardless of host (localhost, IP, or Docker service name).
const apiClient = axios.create({
  // Default to localhost:8000 if the build arg was missing
  baseURL: import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000',
});

// Response interceptor for global error handling
apiClient.interceptors.response.use(
  (response) => response,
  (error) => {
    const message = error.response?.data?.detail || error.message || 'An unexpected error occurred';
    console.error('[API Error]:', message);
    return Promise.reject(error);
  }
);

export default apiClient;

