      <div className="bg-neutral-900 border border-neutral-800 rounded-2xl p-12 flex flex-col items-center justify-center gap-4 text-red-500">
        <AlertCircle className="w-8 h-8" />
        <p className="text-sm font-medium">Failed to load HSV data. Ensure calibration images are assigned.</p>
      </div>
    );
  }

  const { dataset_debug_info, multivariate_color_profile } = data;

  // Helper: HSV to Cartesian (Cylindrical Projection)
  // Matching Tkinter logic: X = S * cos(H_rad), Y = S * sin(H_rad), Z = V
  const toCartesian = (h: number, s: number, v: number) => {
    // OpenCV Hue is 0-179 => 0-360 degrees => Radians
    const h_rad = h * (2 * Math.PI / 180.0);
    const x = s * Math.cos(h_rad);
    const y = s * Math.sin(h_rad);
    const z = v;
    return { x, y, z };
  };

  const allPoints: any[] = [];
  dataset_debug_info.forEach((item: any) => {
    const filename = item.path.split(/[\\/]/).pop();

    item.hsv_colors.forEach((hsv: number[], idx: number) => {
      // Python BGR -> RGB
      const bgr = item.bgr_colors[idx];
      const rgb = [bgr[2], bgr[1], bgr[0]];
      const isOutlier = item.outlier_mask?.[idx] || false;

      const { x, y, z } = toCartesian(hsv[0], hsv[1], hsv[2]);

      allPoints.push({ 
        x, y, z, 
        h: hsv[0], s: hsv[1], v: hsv[2], 
        rgb, 
        isInside: !isOutlier, 
        source: filename 
      });
    });
  });

  const insidePoints = allPoints.filter(p => p.isInside);
  const outsidePoints = allPoints.filter(p => !p.isInside);

