    name: 'Inliers (Support)',
    hovertext: insidePoints.map(p => `Image: ${p.source}`),
    hovertemplate: '<b>%{hovertext}</b><br>H: %{customdata[0]:.1f}<br>S: %{customdata[1]:.1f}<br>V: %{customdata[2]:.1f}<extra></extra>',
    customdata: insidePoints.map(p => [p.h, p.s, p.v]),
    marker: {
      size: 3, // Matches Tkinter size
      color: insidePoints.map(p => `rgb(${p.rgb[0]},${p.rgb[1]},${p.rgb[2]})`),
      opacity: 0.6
    }
  };

  const traceOutside: any = {
    x: outsidePoints.map(p => p.x),
    y: outsidePoints.map(p => p.y),
    z: outsidePoints.map(p => p.z),
    mode: 'markers',
    type: 'scatter3d',
    name: 'Outliers',
    hovertext: outsidePoints.map(p => `Image: ${p.source}`),
    hovertemplate: '<b>%{hovertext}</b><br><span style="color:red">OUTLIER</span><br>H: %{customdata[0]:.1f}<br>S: %{customdata[1]:.1f}<br>V: %{customdata[2]:.1f}<extra></extra>',
    customdata: outsidePoints.map(p => [p.h, p.s, p.v]),
    marker: {
      size: 3, // Matches Tkinter size
      // Removed 'x' symbol to match Tkinter style
      color: outsidePoints.map(p => `rgb(${p.rgb[0]},${p.rgb[1]},${p.rgb[2]})`),
      opacity: 0.8
    }
  };

  // --- ELLIPSOID SURFACE GENERATION ---
  // Replicating Tkinter's parametric sphere transformation logic
  const surfaceTraces: any[] = [];
  if (multivariate_color_profile?.transform_matrix) {
    try {
      const centroid = multivariate_color_profile.centroid; // [x, y, z]
      const M = multivariate_color_profile.transform_matrix; // 3x3 matrix

      const resolution = 40; // 40x40 grid like Tkinter
      const xGrid: number[][] = [];
      const yGrid: number[][] = [];
      const zGrid: number[][] = [];

      for (let i = 0; i < resolution; i++) {
        const phi = (i / (resolution - 1)) * 2 * Math.PI; // 0..2PI
        const xRow: number[] = [];
        const yRow: number[] = [];
        const zRow: number[] = [];

        for (let j = 0; j < resolution; j++) {
          const theta = (j / (resolution - 1)) * Math.PI; // 0..PI

          // Parametric Sphere
          const xs = Math.cos(phi) * Math.sin(theta);
          const ys = Math.sin(phi) * Math.sin(theta);
          const zs = Math.cos(theta);

          // Transform: X_ell = X_sphere @ M.T + Centroid
