        yGrid.push(yRow);
        zGrid.push(zRow);
      }

      surfaceTraces.push({
        type: 'surface',
        x: xGrid,
        y: yGrid,
        z: zGrid,
        opacity: 0.2, // Matches Tkinter
        colorscale: 'Blues',
        showscale: false,
