    item.hsv_colors.forEach((hsv: number[], idx: number) => {
      // Python BGR -> RGB for display
      const bgr = item.bgr_colors[idx];
      const rgb = [bgr[2], bgr[1], bgr[0]];

      const isOutlier = item.outlier_mask?.[idx] || false;

      allPoints.push({ hsv, rgb, isInside: !isOutlier, source: filename });
    });
  });

  const insidePoints = allPoints.filter(p => p.isInside);
  const outsidePoints = allPoints.filter(p => !p.isInside);

  const traceInside: any = {
    x: insidePoints.map(p => p.hsv[0]),
    y: insidePoints.map(p => p.hsv[1]),
    z: insidePoints.map(p => p.hsv[2]),
    mode: 'markers',
    type: 'scatter3d',
    name: 'Inlier (Support Set)',
    hovertext: insidePoints.map(p => `Image: ${p.source}`),
    hovertemplate: '<b>%{hovertext}</b><br>H: %{x:.1f}<br>S: %{y:.1f}<br>V: %{z:.1f}<extra></extra>',
    marker: {
      size: 4,
      color: insidePoints.map(p => `rgb(${p.rgb[0]},${p.rgb[1]},${p.rgb[2]})`),
      opacity: 0.8
    }
  };

  const traceOutside: any = {
    x: outsidePoints.map(p => p.hsv[0]),
    y: outsidePoints.map(p => p.hsv[1]),
    z: outsidePoints.map(p => p.hsv[2]),
    mode: 'markers',
    type: 'scatter3d',
    name: 'Multivariate Outliers',
    hovertext: outsidePoints.map(p => `Image: ${p.source}`),
    hovertemplate: '<b>%{hovertext}</b><br><span style="color:red">OUTLIER</span><br>H: %{x:.1f}<br>S: %{y:.1f}<br>V: %{z:.1f}<extra></extra>',
    marker: {
      size: 6,
      symbol: 'x',
      color: outsidePoints.map(p => `rgb(${p.rgb[0]},${p.rgb[1]},${p.rgb[2]})`),
      line: {
        color: 'red',
        width: 1
      },
      opacity: 1
    }
  };

  // --- ELLIPSOID MESH GENERATION ---
  const ellipsoidTraces: any[] = [];
  if (multivariate_color_profile?.transform_matrix) {
    try {
      const centroid = multivariate_color_profile.centroid;
      const M = multivariate_color_profile.transform_matrix; // 3x3 matrix

      // 1. Generate a Unit Sphere Grid
      const rows = 25;
      const cols = 25;
      const xMesh: number[] = [];
      const yMesh: number[] = [];
      const zMesh: number[] = [];

      for (let i = 0; i < rows; i++) {
        const phi = (i * Math.PI) / (rows - 1);
        for (let j = 0; j < cols; j++) {
          const theta = (j * 2 * Math.PI) / (cols - 1);

          // Point on unit sphere
          const vx = Math.sin(phi) * Math.cos(theta);
          const vy = Math.sin(phi) * Math.sin(theta);
          const vz = Math.cos(phi);

          // 2. Transform by matrix M and shift by centroid
          const tx = M[0][0] * vx + M[0][1] * vy + M[0][2] * vz + centroid[0];
          const ty = M[1][0] * vx + M[1][1] * vy + M[1][2] * vz + centroid[1];
          const tz = M[2][0] * vx + M[2][1] * vy + M[2][2] * vz + centroid[2];

          xMesh.push(tx);
          yMesh.push(ty);
          zMesh.push(tz);
        }
      }

      const hMesh = xMesh.map((val, i) => {
        let h_rad = Math.atan2(yMesh[i], val);
        // Normalize -PI..PI to 0..2PI
        let h_normalized = h_rad < 0 ? h_rad + 2 * Math.PI : h_rad;
        // Scale to 0..179 (OpenCV Hue)
        return (h_normalized * 180) / (2 * Math.PI);
      });
      const sMesh = xMesh.map((val, i) => Math.sqrt(val * val + yMesh[i] * yMesh[i]));
      const vMesh = zMesh;

      ellipsoidTraces.push({
        type: 'mesh3d',
        x: hMesh,
        y: sMesh,
        z: vMesh,
        alphahull: 0,
        opacity: 0.15,
        color: 'cyan',
        name: 'Confidence Ellipsoid (Boundary)',
        showlegend: true
      });
    } catch (e) {
      console.warn("Ellipsoid visualization failed", e);
    }
  }

  return (
    <div className="bg-neutral-900 border border-neutral-800 rounded-2xl overflow-hidden p-4 animate-in fade-in zoom-in-95 duration-500">
      <div className="flex items-center justify-between mb-4 px-2">
        <div>
          <h3 className="text-lg font-bold text-white">Multivariate Color Distribution</h3>
          <p className="text-[10px] text-neutral-500 uppercase tracking-widest font-bold">
            Unified Robust Ellipsoid Model (97.5% Confidence)
          </p>
        </div>
        <div className="flex gap-4 text-[10px] font-bold">
          <div className="flex items-center gap-1.5">
            <div className="w-2 h-2 rounded-full bg-cyan-500"></div>
            <span className="text-neutral-400">CONFIDENCE ENVELOPE</span>
          </div>
          <div className="flex items-center gap-1.5">
            <div className="w-2 h-2 rounded-full bg-red-500"></div>
            <span className="text-neutral-400">OUTLIERS (X)</span>
          </div>
        </div>
      </div>

      <div className="w-full h-[600px]">
        <Plot
          data={[traceInside, traceOutside, ...ellipsoidTraces]}
          layout={{
            autosize: true,
            paper_bgcolor: 'rgba(0,0,0,0)',
            plot_bgcolor: 'rgba(0,0,0,0)',
            margin: { l: 0, r: 0, b: 0, t: 0 },
            scene: {
              xaxis: { title: { text: 'Hue' }, range: [0, 180], color: '#737373', gridcolor: '#262626' },
              yaxis: { title: { text: 'Saturation' }, range: [0, 255], color: '#737373', gridcolor: '#262626' },
              zaxis: { title: { text: 'Value' }, range: [0, 255], color: '#737373', gridcolor: '#262626' },
              bgcolor: 'rgba(0,0,0,0)'
            },
            legend: {
              font: { color: '#a3a3a3', size: 10 },
              bgcolor: 'rgba(0,0,0,0.5)',
              x: 0, y: 1
            }
          }}
          style={{ width: '100%', height: '100%' }}
          config={{ displayModeBar: true, responsive: true }}
        />
      </div>
    </div>
  );
};
